from list_comprehensions import filter_positive_even_numbers


def test_filter_positive_and_negatives():
    numbers = list(range(-10, 11))
    assert filter_positive_even_numbers(numbers) == [2, 4, 6, 8, 10]


def test_only_positives():
    numbers = [2, 4, 51, 44, 47, 10]
    assert filter_positive_even_numbers(numbers) == [2, 4, 44, 10]


def test_filter_zero_and_negatives():
    numbers = [0, -1, -3, -5]
    assert filter_positive_even_numbers(numbers) == []

from belts import BeltStats, ninja_belts, get_total_points


def test_get_total_points_given_belts():
    assert get_total_points(ninja_belts) == 2675


def test_get_total_points_more_belts():
    more_belts = dict(brown=BeltStats(400, 2),
                      black=BeltStats(600, 5))

    # this way to dict merge is >= 3.5 (PEP 448)
    ninja_belts_updated = {**ninja_belts, **more_belts}

    assert get_total_points(ninja_belts_updated) == 6475
